答案不唯一，合理即可。解析给出的实现：用 TIM2 更新中断，每次中断翻转亮灯种类，TIM2 计数周期设为 5 s。

```c
void TIM2_IRQHandler()   // 中断服务子程序
{
    if (TIM_GetITStatus(TIM2, TIM_IT_Update) != RESET)
    {
        if (flag)
        {
            LED_GREEN_OFF();   // 对 PB8 写 0
            LED_RED_ON();      // 对 PA18 写 1
        }
        else
        {
            LED_RED_OFF();     // 对 PA18 写 0
            LED_GREEN_ON();    // 对 PB8 写 1
        }
        flag = !flag;          // 反转 flag，这样下一次触发中断时亮不同的灯
    }
}

int main()
{
    int flag = 0;              // 这是中断服务程序中指示当前亮的灯种类的变量
    LED_RED_Config();          // 对 PA18 进行配置
    LED_GREEN_Config();        // 对 PB8 进行配置
    NVIC_PriorityGroupConfig(NVIC_PriorityGroup_2);  // 设置中断优先级
    TIM2_Init(83999, 4999);    // TIM2 初始化，配置 arr 和 psc 使计数周期为 5s 并使能中断
    while (1)
    {
    }
}
```

设计思路：前/后台结构。TIM2 每 1 s 产生一次更新中断作为“秒”时基，主程序按状态机倒计时并驱动红/绿灯；按键接 PC5，用 EXTI5 下降沿中断置标志，主程序检测到标志后立即切换颜色（并重新装入新颜色的时长）。引脚可自行规定，此处取 PB0=红灯、PB1=绿灯、PC5=按键（低电平有效），答案不唯一。

一、硬件原理图（文字描述）
```
        +3.3V
          │
   PB0 ──[510Ω]──▶|──┐        红灯 LED1（灌电流，PB0 输出高电平点亮）
   PB1 ──[510Ω]──▶|──┤        绿灯 LED2（PB1 输出高电平点亮）
                     └──── GND

   PC5 ──┬── KEY0 ── GND      按键按下 = 低电平
         └── 10kΩ ── +3.3V    （也可只用内部上拉 GPIO_Mode_IPU）
```
其余按最小系统连接：3.3 V 电源与去耦电容、8 MHz 晶振 + 2×20 pF、32.768 kHz RTC 晶振（可选）、NRST 复位电路、BOOT0/BOOT1 接地、SWD 调试口。

二、程序（前/后台）
```c
#include "stm32f10x.h"

volatile unsigned char tick1s    = 0;   /* TIM2 每秒置 1 */
volatile unsigned char keyFlag   = 0;   /* 按键中断置 1 */
#define RED    0
#define GREEN  1

void LED_Config(void);
void KEY_Config(void);
void EXTI_Config(void);
void NVIC_Config(void);
void TIM2_Config(void);
void ShowColor(unsigned char state);

int main(void)
{
    unsigned char state  = RED;
    unsigned char remain = 20;          /* 红灯先亮 20 s */

    LED_Config(); KEY_Config(); EXTI_Config(); NVIC_Config(); TIM2_Config();
    ShowColor(state);

    while (1) {
        if (keyFlag) {                  /* 按键：立即换色 */
            keyFlag = 0;
            tick1s  = 0;                /* 丢弃本次秒标志，新颜色从整秒开始计时 */
            state   = !state;
            remain  = (state == RED) ? 20 : 30;
            ShowColor(state);
        }
        else if (tick1s) {              /* 每满 1 s 减 1 */
            tick1s = 0;
            if (--remain == 0) {
                state  = !state;
                remain = (state == RED) ? 20 : 30;
                ShowColor(state);
            }
        }
    }
}

void ShowColor(unsigned char state)
{
    if (state == RED) {
        GPIO_SetBits(GPIOB, GPIO_Pin_0);
        GPIO_ResetBits(GPIOB, GPIO_Pin_1);
    } else {
        GPIO_ResetBits(GPIOB, GPIO_Pin_0);
        GPIO_SetBits(GPIOB, GPIO_Pin_1);
    }
}

void LED_Config(void)
{
    GPIO_InitTypeDef g;
    RCC_APB2PeriphClockCmd(RCC_APB2Periph_GPIOB, ENABLE);
    g.GPIO_Pin   = GPIO_Pin_0 | GPIO_Pin_1;
    g.GPIO_Mode  = GPIO_Mode_Out_PP;
    g.GPIO_Speed = GPIO_Speed_2MHz;
    GPIO_Init(GPIOB, &g);
}

void KEY_Config(void)
{
    GPIO_InitTypeDef g;
    RCC_APB2PeriphClockCmd(RCC_APB2Periph_GPIOC, ENABLE);
    g.GPIO_Pin   = GPIO_Pin_5;
    g.GPIO_Mode  = GPIO_Mode_IPU;       /* 上拉输入，按下为低 */
    g.GPIO_Speed = GPIO_Speed_2MHz;
    GPIO_Init(GPIOC, &g);
}

void EXTI_Config(void)
{
    EXTI_InitTypeDef e;
    RCC_APB2PeriphClockCmd(RCC_APB2Periph_AFIO, ENABLE);
    GPIO_EXTILineConfig(GPIO_PortSourceGPIOC, GPIO_PinSource5);
    e.EXTI_Line    = EXTI_Line5;
    e.EXTI_Mode    = EXTI_Mode_Interrupt;
    e.EXTI_Trigger = EXTI_Trigger_Falling;
    e.EXTI_LineCmd = ENABLE;
    EXTI_Init(&e);
}

void NVIC_Config(void)
{
    NVIC_InitTypeDef n;
    NVIC_PriorityGroupConfig(NVIC_PriorityGroup_1);   /* 1 位抢占 + 3 位子优先级 */

    n.NVIC_IRQChannel = TIM2_IRQn;
    n.NVIC_IRQChannelPreemptionPriority = 1;
    n.NVIC_IRQChannelSubPriority        = 0;
    n.NVIC_IRQChannelCmd                = ENABLE;
    NVIC_Init(&n);

    n.NVIC_IRQChannel = EXTI9_5_IRQn;                 /* 按键抢占优先级更高 */
    n.NVIC_IRQChannelPreemptionPriority = 0;
    n.NVIC_IRQChannelSubPriority        = 1;
    NVIC_Init(&n);
}

void TIM2_Config(void)                  /* TIM2 定时 1 s，开更新中断 */
{
    TIM_TimeBaseInitTypeDef t;
    RCC_APB1PeriphClockCmd(RCC_APB1Periph_TIM2, ENABLE);
    /* TIM2CLK=72MHz（APB1 分频≠1 时定时器时钟×2）
       72MHz/(7199+1)=10kHz；(10kHz)/(9999+1)=1Hz，即 1 s 一次更新 */
    t.TIM_Prescaler     = 7200 - 1;
    t.TIM_Period        = 10000 - 1;
    t.TIM_ClockDivision = TIM_CKD_DIV1;
    t.TIM_CounterMode   = TIM_CounterMode_Up;
    TIM_TimeBaseInit(TIM2, &t);
    TIM_ClearFlag(TIM2, TIM_FLAG_Update);
    TIM_ITConfig(TIM2, TIM_IT_Update, ENABLE);
    TIM_Cmd(TIM2, ENABLE);
}
```
```c
/* stm32f10x_it.c */
#include "stm32f10x_it.h"
extern volatile unsigned char tick1s;
extern volatile unsigned char keyFlag;

void TIM2_IRQHandler(void)
{
    if (TIM_GetITStatus(TIM2, TIM_IT_Update) != RESET) {
        tick1s = 1;                             /* 只置标志，处理放主程序 */
        TIM_ClearITPendingBit(TIM2, TIM_IT_Update);
    }
}

void EXTI9_5_IRQHandler(void)
{
    if (EXTI_GetITStatus(EXTI_Line5) != RESET) {
        keyFlag = 1;
        EXTI_ClearITPendingBit(EXTI_Line5);
    }
}
```
三、说明
(1) 时基精度：TIM2 分频与重装值均为整数，1 s 无累加误差；若要求更高精度可用 72 MHz/(PSC+1)/(ARR+1)=1 Hz 的同一算式取 PSC=7199、ARR=9999 亦可（72MHz/7200=10kHz，10kHz/10000=1Hz）。
(2) 按键“强行换色”的语义：不论当前颜色已亮多久，按下即切到另一种颜色，并把新颜色的计时重新置满（20 s 或 30 s）；若希望保留剩余时间，改为只翻转 state、不重装 remain 即可。
(3) 消抖：ISR 只置标志，如需消抖可在主程序判断 keyFlag 后再延时 10~20 ms 复测 PC5 电平，或在 PC5 与按键间加 RC 低通；不要在 ISR 中长时间延时。
(4) 抢占优先级设置保证按键（抢占 0）能打断 TIM2（抢占 1）的 ISR，响应更及时。

采用查询方式（也可用中断/DMA），USART1 引脚为 PA9(TX)、PA10(RX)，配置 115200、8N1，然后用循环逐字符发出字符串并以 TC 确认最后一帧发送完毕。

```c
#include "stm32f10x.h"

void USART1_Config(unsigned int baud);
void USART1_SendChar(unsigned char ch);
void USART1_SendString(const char *s);

int main(void)
{
    USART1_Config(115200);
    USART1_SendString("you are welcome");
    while (1);
}

void USART1_Config(unsigned int baud)
{
    GPIO_InitTypeDef  GPIO_InitStructure;
    USART_InitTypeDef USART_InitStructure;

    RCC_APB2PeriphClockCmd(RCC_APB2Periph_GPIOA | RCC_APB2Periph_USART1, ENABLE);

    GPIO_InitStructure.GPIO_Pin   = GPIO_Pin_9;              /* PA9 = TXD */
    GPIO_InitStructure.GPIO_Mode  = GPIO_Mode_AF_PP;         /* 复用推挽输出 */
    GPIO_InitStructure.GPIO_Speed = GPIO_Speed_50MHz;
    GPIO_Init(GPIOA, &GPIO_InitStructure);

    GPIO_InitStructure.GPIO_Pin  = GPIO_Pin_10;              /* PA10 = RXD */
    GPIO_InitStructure.GPIO_Mode = GPIO_Mode_IN_FLOATING;    /* 浮空输入 */
    GPIO_Init(GPIOA, &GPIO_InitStructure);

    USART_InitStructure.USART_BaudRate            = baud;
    USART_InitStructure.USART_WordLength          = USART_WordLength_8b;
    USART_InitStructure.USART_StopBits            = USART_StopBits_1;
    USART_InitStructure.USART_Parity              = USART_Parity_No;
    USART_InitStructure.USART_HardwareFlowControl = USART_HardwareFlowControl_None;
    USART_InitStructure.USART_Mode                = USART_Mode_Tx | USART_Mode_Rx;
    USART_Init(USART1, &USART_InitStructure);

    USART_Cmd(USART1, ENABLE);
}

void USART1_SendChar(unsigned char ch)
{
    while (USART_GetFlagStatus(USART1, USART_FLAG_TXE) == RESET);  /* 等 TDR 空 */
    USART_SendData(USART1, ch);                                    /* 写 TDR */
}

void USART1_SendString(const char *s)
{
    while (*s) USART1_SendChar((unsigned char)*s++);
    while (USART_GetFlagStatus(USART1, USART_FLAG_TC) == RESET);   /* 等最后一帧移出 */
}
```
说明：
(1) 先等 TXE=1 再写 DR，可保证上一个字节已从 TDR 搬到 TSR，不会覆盖；
(2) 字符串发完还要等 TC=1，否则程序退出/关闭串口可能截断最后一个字节；
(3) 若用 printf 输出，需重定向 fputc：等待 TC 后调用 USART_SendData；
(4) 若改用中断方式，只需在 USART1_IRQHandler 的 TXE 分支里从缓冲区取下一个字符写入 DR，全部发完后关 TXEIE 并等待 TC。

采用“环形缓冲区（软件 FIFO）+ TXE/RXNE 中断”的通用驱动：应用层只做入队/出队，中断里搬 1 个字节，主程序与中断通过 head/tail 指针解耦，全程无忙等。

一、接口 uart.h
```c
#ifndef UART_H
#define UART_H
#include <stdint.h>

void     uart_init(uint32_t baud);                    /* 初始化 USART1 + NVIC */
void     uart_putc(uint8_t c);                        /* 阻塞发送 1 字节（查询 TXE） */
uint16_t uart_write(const uint8_t *p, uint16_t n);    /* 中断发送，返回成功入队字节数 */
uint16_t uart_read(uint8_t *p, uint16_t n);           /* 从接收 FIFO 取出至多 n 字节 */
uint16_t uart_rx_avail(void);                         /* 接收 FIFO 中可读字节数 */
void     uart_flush(void);                            /* 清空收发 FIFO */
#endif
```

二、实现 uart.c
```c
#include "stm32f10x.h"
#include "uart.h"

#define TX_SIZE 256u
#define RX_SIZE 256u

static volatile uint8_t  tx_buf[TX_SIZE];
static volatile uint16_t tx_head, tx_tail;   /* 中断读 head，主程序写 head */
static volatile uint8_t  rx_buf[RX_SIZE];
static volatile uint16_t rx_head, rx_tail;   /* 中断写 head，主程序写 tail */
static volatile uint8_t  tx_busy;
static volatile uint16_t rx_ovr;             /* 过载计数，便于诊断 */

static uint16_t nxt(uint16_t i, uint16_t size) { return (uint16_t)((i + 1u) % size); }

void uart_init(uint32_t baud)
{
    GPIO_InitTypeDef  g;
    USART_InitTypeDef u;
    NVIC_InitTypeDef  n;

    RCC_APB2PeriphClockCmd(RCC_APB2Periph_GPIOA | RCC_APB2Periph_USART1, ENABLE);

    g.GPIO_Pin = GPIO_Pin_9;  g.GPIO_Mode = GPIO_Mode_AF_PP;
    g.GPIO_Speed = GPIO_Speed_50MHz;  GPIO_Init(GPIOA, &g);
    g.GPIO_Pin = GPIO_Pin_10; g.GPIO_Mode = GPIO_Mode_IN_FLOATING;
    GPIO_Init(GPIOA, &g);

    u.USART_BaudRate = baud;
    u.USART_WordLength = USART_WordLength_8b;
    u.USART_StopBits = USART_StopBits_1;
    u.USART_Parity = USART_Parity_No;
    u.USART_HardwareFlowControl = USART_HardwareFlowControl_None;
    u.USART_Mode = USART_Mode_Rx | USART_Mode_Tx;
    USART_Init(USART1, &u);
    USART_Cmd(USART1, ENABLE);

    /* 只开 RXNE 中断；TXE 中断在有待发数据时才开，避免空转 */
    USART_ITConfig(USART1, USART_IT_RXNE, ENABLE);
    n.NVIC_IRQChannel = USART1_IRQn;
    n.NVIC_IRQChannelPreemptionPriority = 1;
    n.NVIC_IRQChannelSubPriority = 0;
    n.NVIC_IRQChannelCmd = ENABLE;
    NVIC_Init(&n);
}

void uart_putc(uint8_t c)
{
    while (USART_GetFlagStatus(USART1, USART_FLAG_TXE) == RESET);
    USART_SendData(USART1, c);
}

uint16_t uart_write(const uint8_t *p, uint16_t n)
{
    uint16_t cnt = 0, nh;
    while (cnt < n) {
        nh = nxt(tx_head, TX_SIZE);
        if (nh == tx_tail) break;              /* FIFO 满，返回已入队长度 */
        tx_buf[tx_head] = p[cnt++];
        tx_head = nh;
    }
    if (!tx_busy && tx_head != tx_tail) {      /* 启动发送：先写 1 字节再开 TXEIE */
        tx_busy = 1;
        USART_SendData(USART1, tx_buf[tx_tail]);
        tx_tail = nxt(tx_tail, TX_SIZE);
        USART_ITConfig(USART1, USART_IT_TXE, ENABLE);
    }
    return cnt;
}

uint16_t uart_rx_avail(void)
{
    return (uint16_t)((rx_head + RX_SIZE - rx_tail) % RX_SIZE);
}

uint16_t uart_read(uint8_t *p, uint16_t n)
{
    uint16_t cnt = 0;
    while (cnt < n && rx_tail != rx_head) {
        p[cnt++] = rx_buf[rx_tail];
        rx_tail = nxt(rx_tail, RX_SIZE);
    }
    return cnt;
}

void uart_flush(void)
{
    USART_ITConfig(USART1, USART_IT_TXE, DISABLE);
    tx_head = tx_tail = 0;  tx_busy = 0;
    rx_head = rx_tail = 0;  rx_ovr  = 0;
}

/* 收/发共用一个向量，ISR 内先判别中断源 */
void USART1_IRQHandler(void)
{
    if (USART_GetITStatus(USART1, USART_IT_RXNE) != RESET) {
        uint8_t  d = (uint8_t)USART_ReceiveData(USART1);   /* 读 DR 同时清 RXNE/ORE */
        uint16_t h = rx_head, nh = nxt(h, RX_SIZE);
        if (nh != rx_tail) { rx_buf[h] = d; rx_head = nh; }
        else               { rx_ovr++; }                   /* FIFO 满则丢弃新字节 */
    }
    if (USART_GetITStatus(USART1, USART_IT_TXE) != RESET) {
        if (tx_tail != tx_head) {
            USART_SendData(USART1, tx_buf[tx_tail]);
            tx_tail = nxt(tx_tail, TX_SIZE);
        } else {                                           /* 队列空：关中断、清忙标志 */
            USART_ITConfig(USART1, USART_IT_TXE, DISABLE);
            tx_busy = 0;
        }
    }
}
```

三、设计要点
(1) 中断负载低：只有真有数据要发时才开 TXEIE，队列空即关，避免 TXE 中断一直空转刷 CPU。
(2) 无锁：单生产者/单消费者，head 只由一方写、tail 只由另一方写，16 位赋值在 Cortex-M3 上是原子的，无需临界区；容量取 256 使取模退化为按位与（%256）。
(3) 可靠：缓冲满时 uart_write 返回实际入队长度、接收满时丢弃并累计 rx_ovr，不阻塞、不丢指针。
(4) 关于“硬件 FIFO”：STM32F103 的 USART 只有 1 字节 TDR/RDR，没有硬件 FIFO，题目要求的 FIFO 只能由上述软件环形缓冲实现（这是 F103 的硬件限制）；若换用带 FIFO 的型号（如 STM32F0/F3/F7/L4 的 USART），应置 CR1.FIFOEN=1，按 CR3.RXFTCFG 设接收触发阈值、用 RXFT/TXFT 中断，一次中断搬一批数据，中断次数进一步下降。
(5) 大数据块可用 DMA：uart_write 改为启动 DMA（CR3.DMAT=1，DMA 通道内存→DR），RXNE 触发 DMA 写传送；DMA 半传输/传输完成中断与环形缓冲配合可实现零拷贝接收。

