(1) 一帧共 16 个 SCLK 周期 = **2 字节**：4（起始，SID 保持 H）+ 1（RW）+ 1（RS）+ 2（SID 保持 L）+ 8（D7~D0）= 16 bit。

(2) 位带宏定义（外设位带区 0x4000 0000，别名区 0x4200 0000）：

```c
/* DEVICE_REG0 地址 0x4000 2024；bit0 = SCLK，bit1 = SID
   别名地址 = 0x42000000 + (0x40002024 - 0x40000000)*32 + bit*4
            = 0x42040480 + bit*4                                    */
#define SCLK   (*(volatile unsigned int *)0x42040480)   /* DEVICE_REG0.bit0 */
#define SID    (*(volatile unsigned int *)0x42040484)   /* DEVICE_REG0.bit1 */

/* 通用写法 */
#define BITBAND(addr, bit) \
    (*(volatile unsigned int *)(0x42000000 + (((unsigned int)(addr)) - 0x40000000) * 32 + (bit) * 4))
/* #define SCLK BITBAND(0x40002024, 0)    #define SID BITBAND(0x40002024, 1) */
```

(3) 数据发送函数（SCLK 200kHz → 周期 5µs，半周期约 2.5µs；SID 在 SCLK 低电平期间改变，高电平期间保持）：

```c
typedef unsigned char u8;

/* 发送 1 位：低电平改变 SID，高电平期间数据稳定被外设采样 */
static void SendBit(u8 b)
{
    SCLK = 0;  delay_us(2);      /* 时钟低：允许 SID 变化 */
    SID  = b;  delay_us(1);
    SCLK = 1;  delay_us(2);      /* 时钟高：外设采样 */
}

void SendByte(u8 byte)
{
    u8 i;
    SCLK = 0;

    /* 1) 起始段：SID 连续 4 个时钟为 1 */
    for (i = 0; i < 4; i++) SendBit(1);

    /* 2) RW = 0：数据由 MCU 发往外设 */
    SendBit(0);

    /* 3) RS = 1：本次字节为有效数据 */
    SendBit(1);

    /* 4) RS 之后 SID 保持 2 个时钟为 0 */
    SendBit(0);
    SendBit(0);

    /* 5) 数据 D7~D0，高位在前 */
    for (i = 0; i < 8; i++) SendBit((byte >> (7 - i)) & 0x01);

    SCLK = 0;                    /* 帧结束，时钟回到低电平 */
}
```

(4) 0x88 是控制指令，需 RS = 0（发数据时 RS = 1），把 RS 作为参数传入即可复用同一帧结构：

```c
void SendByte(u8 byte, u8 rs);          /* rs = 1 发数据，rs = 0 发指令 */
...
    SendBit(0);        /* RW = 0 */
    SendBit(rs);       /* RS：数据 / 指令 */
...

/* 发送指令 0x88（1000 1000B） */
SendByte(0x88, 0);
```
